struct Counting<W> { inner: W, bytes: u64 }

impl<W: Write> Write for Counting<W> {
    fn write(&mut self, buf: &[u8]) -> std::io::Result<usize> {
        let n = self.inner.write(buf)?;             // delegate
        self.bytes += n as u64;
        Ok(n)
    }
    fn flush(&mut self) -> std::io::Result<()> { self.inner.flush() }
}

let mut out = Counting { inner: BufWriter::new(File::create("out")?), bytes: 0 };
